PRAGMA defer_foreign_keys=ON;
CREATE TABLE schema_version_v5(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3,4,5)),backend TEXT NOT NULL CHECK(backend='sqlite'),checksum TEXT NOT NULL) STRICT;
