CREATE TABLE team_membership(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,team_id TEXT NOT NULL,is_primary INTEGER NOT NULL DEFAULT 1 CHECK(is_primary IN(0,1)),valid_from TEXT NOT NULL CHECK( (length(valid_from)=10 AND date(valid_from,'+0 days') IS NOT NULL AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR  (length(valid_to)=10 AND date(valid_to,'+0 days') IS NOT NULL AND date(valid_to,'+0 days')=valid_to)),effective_to TEXT CHECK(effective_to IS NULL OR  (length(effective_to)=10 AND date(effective_to,'+0 days') IS NOT NULL AND date(effective_to,'+0 days')=effective_to)),superseded INTEGER NOT NULL DEFAULT 0 CHECK(superseded IN(0,1)),change_id TEXT NOT NULL,end_change_id TEXT,supersedes_id TEXT CHECK(supersedes_id IS NULL OR supersedes_id<>id),CHECK(valid_to IS NULL OR valid_from<valid_to),CHECK(effective_to IS NULL OR valid_from<effective_to),CHECK((effective_to IS NULL AND end_change_id IS NULL) OR (effective_to IS NOT NULL AND end_change_id IS NOT NULL)),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,end_change_id) REFERENCES structure_change(org_id,id),PRIMARY KEY(org_id,id),UNIQUE(id),UNIQUE(org_id,employee_id,id),UNIQUE(org_id,team_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,team_id) REFERENCES team(org_id,id),FOREIGN KEY(org_id,employee_id,supersedes_id) REFERENCES team_membership(org_id,employee_id,id),CHECK(is_primary=1)) STRICT;
CREATE TABLE position_assignment(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,team_id TEXT,is_primary INTEGER NOT NULL DEFAULT 1 CHECK(is_primary IN(0,1)),valid_from TEXT NOT NULL CHECK( (length(valid_from)=10 AND date(valid_from,'+0 days') IS NOT NULL AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR  (length(valid_to)=10 AND date(valid_to,'+0 days') IS NOT NULL AND date(valid_to,'+0 days')=valid_to)),effective_to TEXT CHECK(effective_to IS NULL OR  (length(effective_to)=10 AND date(effective_to,'+0 days') IS NOT NULL AND date(effective_to,'+0 days')=effective_to)),superseded INTEGER NOT NULL DEFAULT 0 CHECK(superseded IN(0,1)),change_id TEXT NOT NULL,end_change_id TEXT,supersedes_id TEXT CHECK(supersedes_id IS NULL OR supersedes_id<>id),payload_id TEXT NOT NULL,CHECK(valid_to IS NULL OR valid_from<valid_to),CHECK(effective_to IS NULL OR valid_from<effective_to),CHECK((effective_to IS NULL AND end_change_id IS NULL) OR (effective_to IS NOT NULL AND end_change_id IS NOT NULL)),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,end_change_id) REFERENCES structure_change(org_id,id),PRIMARY KEY(org_id,id),UNIQUE(id),UNIQUE(org_id,employee_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,team_id) REFERENCES team(org_id,id),FOREIGN KEY(org_id,employee_id,supersedes_id) REFERENCES position_assignment(org_id,employee_id,id),CHECK(is_primary=1),FOREIGN KEY(org_id,employee_id,id,payload_id) REFERENCES organizational_payload(org_id,employee_id,position_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
