CREATE TABLE team_lifecycle_history(org_id TEXT NOT NULL,id TEXT NOT NULL,team_id TEXT NOT NULL,valid_from TEXT NOT NULL CHECK( (length(valid_from)=10 AND date(valid_from,'+0 days') IS NOT NULL AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR  (length(valid_to)=10 AND date(valid_to,'+0 days') IS NOT NULL AND date(valid_to,'+0 days')=valid_to)),change_id TEXT,supersedes_id TEXT CHECK(supersedes_id IS NULL OR supersedes_id<>id),CHECK(valid_to IS NULL OR valid_from<valid_to),PRIMARY KEY(org_id,id),UNIQUE(org_id,team_id,id),FOREIGN KEY(org_id,team_id) REFERENCES team(org_id,id),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,team_id,supersedes_id) REFERENCES team_lifecycle_history(org_id,team_id,id)) STRICT;
CREATE TABLE employee_lifecycle_history(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,valid_from TEXT NOT NULL CHECK( (length(valid_from)=10 AND date(valid_from,'+0 days') IS NOT NULL AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR  (length(valid_to)=10 AND date(valid_to,'+0 days') IS NOT NULL AND date(valid_to,'+0 days')=valid_to)),change_id TEXT,supersedes_id TEXT CHECK(supersedes_id IS NULL OR supersedes_id<>id),CHECK(valid_to IS NULL OR valid_from<valid_to),PRIMARY KEY(org_id,id),UNIQUE(org_id,employee_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,employee_id,supersedes_id) REFERENCES employee_lifecycle_history(org_id,employee_id,id)) STRICT;
