CREATE TABLE organizational_payload(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,employee_id TEXT,team_id TEXT,position_id TEXT,change_id TEXT,record_id TEXT NOT NULL,version_id TEXT NOT NULL CHECK(version_id=id),object_kind TEXT NOT NULL CHECK(object_kind IN('team_label','position_assignment','structure_change')),purpose TEXT NOT NULL CHECK(purpose='pii'),schema_type TEXT NOT NULL CHECK(schema_type IN('org.team.label.v1','org.position.v1','org.structure.reason.v1')),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version INTEGER NOT NULL CHECK(kek_version>0),wrapped_dek BLOB NOT NULL CHECK(length(wrapped_dek)>0),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),created_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,team_id,id),UNIQUE(org_id,change_id,id),UNIQUE(org_id,employee_id,position_id,id),FOREIGN KEY(org_id,team_id) REFERENCES team(org_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,employee_id,position_id) REFERENCES position_assignment(org_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id) DEFERRABLE INITIALLY DEFERRED,CHECK((object_kind='team_label' AND schema_type='org.team.label.v1' AND team_id IS NOT NULL AND record_id=team_id AND employee_id IS NULL AND position_id IS NULL AND change_id IS NULL) OR (object_kind='position_assignment' AND schema_type='org.position.v1' AND employee_id IS NOT NULL AND position_id IS NOT NULL AND record_id=position_id AND team_id IS NULL AND change_id IS NULL) OR (object_kind='structure_change' AND schema_type='org.structure.reason.v1' AND change_id IS NOT NULL AND record_id=change_id AND employee_id IS NULL AND team_id IS NULL AND position_id IS NULL))) STRICT;
CREATE TABLE structure_change_item(org_id TEXT NOT NULL,change_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 99),action TEXT NOT NULL CHECK(action IN('add','end','replace','lifecycle')),kind TEXT NOT NULL CHECK(kind IN('team_parent','membership','position','reporting_line','team_lifecycle','employee_lifecycle')),relation_id TEXT,employee_id TEXT,team_id TEXT,manager_employee_id TEXT,parent_team_id TEXT,valid_from TEXT CHECK(valid_from IS NULL OR  (length(valid_from)=10 AND date(valid_from,'+0 days') IS NOT NULL AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR  (length(valid_to)=10 AND date(valid_to,'+0 days') IS NOT NULL AND date(valid_to,'+0 days')=valid_to)),end_date TEXT CHECK(end_date IS NULL OR  (length(end_date)=10 AND date(end_date,'+0 days') IS NOT NULL AND date(end_date,'+0 days')=end_date)),supersedes_id TEXT CHECK(supersedes_id IS NULL OR relation_id IS NULL OR supersedes_id<>relation_id),PRIMARY KEY(org_id,change_id,ordinal),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,team_id) REFERENCES team(org_id,id),FOREIGN KEY(org_id,manager_employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,parent_team_id) REFERENCES team(org_id,id),CHECK(valid_to IS NULL OR (valid_from IS NOT NULL AND valid_from<valid_to)),CHECK((action='end' AND end_date IS NOT NULL AND relation_id IS NOT NULL AND kind NOT IN('team_lifecycle','employee_lifecycle')) OR (action IN('add','replace') AND valid_from IS NOT NULL AND relation_id IS NOT NULL AND end_date IS NULL AND kind NOT IN('team_lifecycle','employee_lifecycle')) OR (action='lifecycle' AND kind IN('team_lifecycle','employee_lifecycle') AND valid_from IS NOT NULL AND end_date IS NULL)),CHECK(kind<>'team_lifecycle' OR (team_id IS NOT NULL AND employee_id IS NULL)),CHECK(kind<>'employee_lifecycle' OR (employee_id IS NOT NULL AND team_id IS NULL))) STRICT;
CREATE TABLE subject_employee(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,employee_id TEXT NOT NULL,PRIMARY KEY(org_id,subject_id),UNIQUE(org_id,employee_id),UNIQUE(org_id,subject_id,employee_id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE structure_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-02','OP-ORG-03')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),digest_key_version INTEGER NOT NULL CHECK(digest_key_version=1),result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object'),result_team_id TEXT,result_change_id TEXT,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),auth_epoch INTEGER NOT NULL CHECK(auth_epoch>0),authority_targets_json TEXT NOT NULL CHECK(json_valid(authority_targets_json) AND json_type(authority_targets_json)='array'),PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,result_team_id) REFERENCES team(org_id,id),FOREIGN KEY(org_id,result_change_id) REFERENCES structure_change(org_id,id),CHECK((operation='OP-ORG-02' AND result_team_id IS NOT NULL AND result_change_id IS NULL) OR (operation='OP-ORG-03' AND result_change_id IS NOT NULL AND result_team_id IS NULL))) STRICT;
