'AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND target_subject_id IS NULL AND target_employee_id IS NULL AND identity_digest IS NULL) OR (actor_kind='local_maintenance' AND operation IN('AUTH-BIND','AUTH-UNBIND') AND outcome='allowed' AND purpose='security_administration' AND org_id IS NOT NULL AND subject_id IS NULL AND employee_id IS NULL AND grant_id IS NULL AND actor_uid IS NOT NULL AND actor_uid BETWEEN 0 AND 4294967295 AND actor_host_hash IS NOT NULL AND target_subject_id IS NOT NULL AND identity_digest IS NOT NULL) OR (actor_kind='legacy_unattributed' AND target_employee_id IS NULL AND operation IN('AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND identity_digest IS NULL AND ((target_subject_id IS NULL AND subject_id IS NULL) OR (target_subject_id IS NOT NULL AND subject_id IS NOT NULL AND target_subject_id=subject_id))))) STRICT;
