CREATE TRIGGER team_parent_history_immutable BEFORE UPDATE ON team_parent_history WHEN NEW.org_id IS NOT OLD.org_id OR NEW.id IS NOT OLD.id OR NEW.child_team_id IS NOT OLD.child_team_id OR NEW.parent_team_id IS NOT OLD.parent_team_id OR NEW.valid_from IS NOT OLD.valid_from OR NEW.valid_to IS NOT OLD.valid_to OR NEW.change_id IS NOT OLD.change_id OR NEW.supersedes_id IS NOT OLD.supersedes_id OR (OLD.superseded=1 AND NEW.superseded<>1) BEGIN SELECT RAISE(ABORT,'immutable relation fact'); END;
