CREATE TRIGGER structure_item_team_parent_owner BEFORE INSERT ON structure_change_item WHEN NEW.kind='team_parent' AND (NOT EXISTS(SELECT 1 FROM team_parent_history WHERE org_id=NEW.org_id AND id=NEW.relation_id) OR (NEW.supersedes_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM team_parent_history WHERE org_id=NEW.org_id AND id=NEW.supersedes_id))) BEGIN SELECT RAISE(ABORT,'invalid structure item owner'); END;
